package cli

import "fmt"

// helpText is the AI-oriented top-level help (SPEC G5): `gtx help` and
// `gtx --help` print exactly this, modeled on herdr's help contract.
const helpText = "---\nname: ikesu\ndescription: Terminal workspace manager for AI coding agents. Use this help as an operational contract, not just a command list.\n---\n# ikesu\n\n## When To Use\n\nUse ikesu to run terminal-based coding agents, address panes by stable targets, send durable messages, and run long commands without blocking the requester.\n\n## Agent Rules\n\n- Prefer `ikesu pane current` to resolve your own pane.\n- `IKESU_PANE_ID` is authoritative when present; otherwise pane current resolves the calling process session, then its parent process tree.\n- `IKESU_PANE_ID` is exported as `pN`; pane targets also accept `N`, `%N`, and `p_N`.\n- Do not infer the requester pane from the focused pane, active window, pane list order, or UI selection.\n- If pane identity cannot be resolved, fail closed and ask for `--caller <pane>`.\n- For communication commands, remember: send=talk, run=execute, log=inspect, inbox=pull fallback.\n\n## Usage\n\nikesu [options]\nikesu help\nikesu --help\nikesu send <agent_target> <message>\nikesu inbox [--room <room>]\nikesu log [job_id|--db]\nikesu run --label tests -- cargo test\n\n## Commands\n\n- `ikesu session import-herdr [--source DIR] [--dry-run] [--yes]` previews and imports a herdr v5 session.\n- `ikesu send <agent_target> <message>` sends a durable message to an agent or pane target.\n- `ikesu inbox [--room <room>]` reads queued messages for the current agent.\n- `ikesu msg history|rooms` inspects the durable mailbox.\n- `ikesu log [job_id|--db|--schema]` inspects dispatch and job history; `sqlite3 \"$(ikesu log --db)\"` opens the raw audit DB.\n- `ikesu run --label tests -- cargo test` starts a pane-less background job by default; `--pane` runs it in a new pane.\n- `ikesu run list` lists background jobs; `ikesu run cancel <job_id>` stops one.\n- `ikesu pane current` resolves the exact caller pane.\n- `ikesu pane get <target>` accepts pane numbers, `%N`, `pN`, and `p_N` pane targets.\n- `ikesu machine list|add|rename|remove|enable|disable` manages saved SSH machines.\n- `ikesu --machine <label-or-id> agent|pane|workspace|worktree ...` forwards to a saved machine.\n- `ikesu run --machine <label-or-id> [--sync] -- <command...>` executes remotely with local jobs and logs.\n- `ikesu agent attach <target> [--takeover]` connects directly to one agent terminal; detach with ctrl+b q.\n- `ikesu agent explain <target> [--json]` explains detection; `ikesu agent explain --file PATH --agent LABEL [--json]` evaluates captured text.\n- `ikesu agent <subcommand>` controls agent identity, reads, sends, and startup.\n- `ikesu workspace`, `ikesu tab`, and `ikesu pane` manage session layout through the socket API.\n\n## Essential Agent Recipes\n\n- Report your pane: `ikesu pane report-agent \"$(ikesu pane current)\" --source codex --agent codex --state working`.\n- Run long work: `ikesu run --label tests -- cargo test`.\n- Read job output after completion: `ikesu log <job_id>`.\n- Pull queued room mail: `ikesu inbox --room <room>`.\n- Message another agent: `ikesu send <agent_target> \"status?\"`.\n- Start an agent: `ikesu agent start <name> -- claude`.\n\n## Options\n\n- `--no-session` runs monolithically without server/client.\n- `--session <name>` uses or creates a named persistent session.\n- `--version`, `-version` prints the version.\n- `--help`, `-h` shows this help.\n\n## More Help\n\nRun `ikesu <command> help` for command-specific usage. Config: ~/.config/gtx/config.toml (override with $IKESU_CONFIG).\n"

func (r *runner) helpCLI() int {
	fmt.Fprint(r.out(), helpText)
	return 0
}
